const fs = require('node:fs');
const V = (m) => { console.error('DEVGOV_POSTPROVEN_HARDENING_PROVEN_VIOLATION: ' + m); process.exit(1); };
const H = (m) => { console.error('DEVGOV_POSTPROVEN_HARDENING_PROVEN_HARNESS_ERROR: ' + m); process.exit(2); };
try {
  const p = "docs/architecture/audits/DEVGOV-INVARIANT-PACKS-POSTPROVEN-HARDENING-V1-PROVEN.md";
  let s;
  try { s = fs.readFileSync(p, 'utf8'); }
  catch (e) {
    if (e && e.code === 'ENOENT') V('the PROVEN record does not exist on this tree: ' + p);
    H('cannot read ' + p + ': ' + (e && e.message));
  }
  const req = JSON.parse(process.argv[1]);
  if (!Array.isArray(req) || req.length === 0) H('no required bindings supplied');
  const missing = req.filter((x) => !s.includes(x));
  if (missing.length > 0) V('the PROVEN record lacks required bindings: ' + missing.join(' | '));
  const grab = (label) => {
    const m = new RegExp('\\*\\*' + label + ':\\*\\* `([0-9a-f]{40})`').exec(s);
    return m && m[1];
  };
  const mt = grab('Merge tree'), ct = grab('Candidate tree');
  if (!mt || !ct) V('merge tree / candidate tree are not both stated as 40-hex SHAs');
  if (mt !== ct) V('merge tree ' + mt + ' differs from candidate tree ' + ct + ': finalization is blocked');
  console.log('DEVGOV_POSTPROVEN_HARDENING_PROVEN_OK: record binds required evidence; merge tree == candidate tree ' + mt);
} catch (e) {
  H('unexpected: ' + (e && e.stack ? e.stack : e));
}

